<script setup>
import {computed,ref,watch} from 'vue';import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';
import {state,dispatch,notify,normalize} from '../state';import {storage} from '../storage';import {t,errorText} from '../i18n';
import {threadCatalogueVersions} from '../thread-catalogues.mjs';import {inspectThreadCatalogue,exportThreadCatalogue,catalogueDigest,CATALOGUE_LIMITS} from '../../core/thread-catalogues.mjs';
const open=ref(false),selected=ref('bundled-dmc'),preview=ref(null),error=ref(''),busy=ref(false),confirmed=ref(false),query=ref(''),page=ref(1),operationId=ref('');
const versions=computed(()=>threadCatalogueVersions(state.value)),record=computed(()=>preview.value??versions.value.find(row=>row.id===selected.value)),matches=computed(()=>record.value?.colors.filter(row=>normalize([row.brand,row.range,row.code,row.name].join(' ')).includes(normalize(query.value)))??[]),pages=computed(()=>Math.max(1,Math.ceil(matches.value.length/50))),visible=computed(()=>matches.value.slice((page.value-1)*50,page.value*50));
const exists=computed(()=>preview.value&&versions.value.some(row=>row.name===preview.value.name&&row.version===preview.value.version));watch([query,selected,preview],()=>page.value=1);watch(pages,value=>page.value=Math.min(page.value,value));
async function inspect(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;error.value='';busy.value=true;try{if(file.size>CATALOGUE_LIMITS.bytes)throw Object.assign(new Error(),{code:'file_too_large'});const data=inspectThreadCatalogue(await file.text());preview.value={...data,digest:catalogueDigest(data)};confirmed.value=false;operationId.value=crypto.randomUUID();query.value='';}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function save(){busy.value=true;error.value='';try{const {digest,...catalogue}=preview.value;await dispatch('thread.catalogue.import',{catalogue,confirmed:confirmed.value},operationId.value);selected.value=state.value.threadCatalogues.find(row=>row.digest===digest).id;preview.value=null;notify();}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function download(template=false){busy.value=true;error.value='';try{const data=template?{name:'My personal colours',version:'1',source:'Describe the actual source',license:'Describe your actual permission or private-use conditions',colors:[{brand:'Personal',range:'',code:'001',name:'Example blue',hex:'#336699'}]}:record.value;if(await storage.saveFile({name:template?'ricamo-colour-catalogue-template.json':'ricamo-colour-catalogue.json',data:exportThreadCatalogue(data)}))notify();}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
</script>
<template>
<section class="panel"><div class="panel-heading"><h2>{{t('threadCatalogues')}}</h2></div><div class="panel-body"><p class="field-help">{{t('threadCatalogueHelp')}}</p><button class="button" @click="open=true">{{t('threadCatalogueManage')}}</button></div></section>
<AppDialog v-if="open" :title="t('threadCatalogues')" wide :busy="busy" @close="open=false;preview=null">
 <p class="notice">{{t('threadCatalogueHelp')}}</p><p class="field-help">{{t('threadCatalogueLimits')}}</p><p v-if="error" class="notice error" role="alert">{{error}}</p>
 <div class="form-grid"><FormField :label="t('threadCatalogueVersion')" v-slot="{id}"><select :id="id" v-model="selected" :disabled="Boolean(preview)"><option v-for="row in versions" :key="row.id" :value="row.id">{{row.name}} · {{row.version}}</option></select></FormField><FormField :label="t('threadCatalogueImport')" v-slot="{id}"><input :id="id" type="file" accept=".json,application/json" :disabled="busy" @change="inspect"/></FormField></div>
 <template v-if="record"><h3>{{record.name}} · {{record.version}} · {{record.colors.length}} {{t('colors')}}</h3><FormField :label="t('threadCatalogueSource')" v-slot="{id}"><textarea :id="id" :value="record.source" readonly/></FormField><FormField :label="t('threadCatalogueLicense')" v-slot="{id}"><textarea :id="id" :value="record.license" readonly/></FormField><p class="field-help">SHA-256: {{record.digest}}</p>
 <FormField :label="t('threadSearchColors')" v-slot="{id}"><input :id="id" v-model="query" type="search"/></FormField><div class="table-wrap"><table><thead><tr><th>{{t('brand')}}</th><th>{{t('range')}}</th><th>{{t('code')}}</th><th>{{t('name')}}</th></tr></thead><tbody><tr v-for="row in visible" :key="JSON.stringify([row.brand,row.range,row.code])"><td>{{row.brand}}</td><td>{{row.range}}</td><td><span class="swatch" :style="{background:row.hex}"/> {{row.code}}</td><td>{{row.name}}</td></tr></tbody></table></div><div class="panel-heading"><span>{{t('page')}} {{page}} / {{pages}}</span><div class="actions"><button class="button small" :disabled="page===1" @click="page--">{{t('previousPage')}}</button><button class="button small" :disabled="page===pages" @click="page++">{{t('nextPage')}}</button></div></div></template>
 <template v-if="preview"><p v-if="exists" class="notice warning">{{t('thread_catalogue_immutable')}}</p><label class="checkbox-label"><input v-model="confirmed" type="checkbox"/>{{t('threadCatalogueConfirm')}}</label></template>
 <template #footer><button class="button" :disabled="busy" @click="open=false;preview=null">{{t('close')}}</button><button class="button" :disabled="busy" @click="download(true)">{{t('threadCatalogueTemplate')}}</button><button v-if="!preview" class="button" :disabled="busy" @click="download()">{{t('export')}}</button><button v-else class="button" :disabled="busy" @click="preview=null">{{t('cancel')}}</button><button v-if="preview" class="button primary" :disabled="busy||!confirmed||exists" @click="save">{{t('threadCatalogueStore')}}</button></template>
</AppDialog>
</template>
